 # Only a vanished proc entry is absence; permission/malformed data is unknown.
 known=Path('/proc')/str(o['pid'])/'stat'
 try:
  raw=known.read_text();fields=raw.rsplit(')',1)[1].split();pid=int(raw.split('(',1)[0].strip());ticks=int(fields[19]);state=fields[0];group=int(fields[2]);session=int(fields[3]);wait=int(fields[49]);F.require(pid==o['pid']and ticks==o['startticks']and group==o['pgid']and session==o['sid']and state in['Z','X']and wait==0,'KNOWN_SUPERVISOR_IDENTITY_STATE_OR_EXIT_MISMATCH')
 except FileNotFoundError:pass # recorded stable-Z0 proof, not inferred exit0
 except (OSError,ValueError,IndexError):raise ValueError('KNOWN_SUPERVISOR_PROC_UNREADABLE_OR_MALFORMED')
 for p in Path('/proc').iterdir():
  if not p.name.isdigit():continue
  try:f=(p/'stat').read_text().rsplit(')',1)[1].split();pid=int(p.name);ticks=int(f[19]);state=f[0];group,session=int(f[2]),int(f[3])
  except (OSError,ValueError,IndexError):continue
  if pid==o['pid']and ticks==o['startticks']or group==o['pgid']or session==o['sid']:F.require(state in['Z','X'],'KNOWN_OWNED_PROCESS_STILL_LIVE')

